import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, RangeSliderChangeEventDetails, SliderThumbSize } from '../../types';

/**
 * @nativeEvent change - dispatched when one of the values changes. Contains both fromValue and toValue in the event.detail object.
 *
 * @slot label - named slot 'label', here is any HTML content allowed.
 * @slot description - named slot 'description', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-range-slider',
  styleUrl: 'range-slider.scss',
  shadow: true,
})
export class RangeSlider {
  /**
   * minimum value
   */
  @Prop({ reflect: true }) readonly min: number = 0;

  /**
   * maximum value
   */
  @Prop({ reflect: true }) readonly max: number = 100;

  /**
   * size of the thumb
   */
  @Prop({ reflect: true }) readonly thumbSize: SliderThumbSize = 'l';

  /**
   * step size. minimum 0.01
   */
  @Prop({ reflect: true }) readonly step: number = 1;

  /**
   * selected from value
   */
  @Prop({ reflect: true, mutable: true }) fromValue: number = this.min;

  /**
   * selected to value
   */
  @Prop({ reflect: true, mutable: true }) toValue: number = this.max;

  /**
   * sets slider to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * activates tick marks
   */
  @Prop({ reflect: true }) readonly showTickMarks: boolean;

  /**
   * custom template for displaying the current value.
   * Use '{fromValue}' and '{toValue}' as placeholders, i.e. '{fromValue}% to {toValue}%' for 25% to 50%
   */
  @Prop({ reflect: true }) readonly valueTemplate: string;

  /**
   * activates tooltip on drag
   */
  @Prop({ reflect: true }) readonly showDragTooltip: boolean;

  /**
   * aria-label for the from-value
   */
  @Prop({ reflect: true, attribute: 'a11y-label-from' }) readonly a11yLabelFrom: string;

  /**
   * aria-label for the to-value
   */
  @Prop({ reflect: true, attribute: 'a11y-label-to' }) readonly a11yLabelTo: string;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<RangeSliderChangeEventDetails>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @State() private isFirstThumbDragged: boolean = false;
  @State() private isSecondThumbDragged: boolean = false;

  @Element() host: HTMLElement;

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (this.disabled) return;

    if (event.code === 'ArrowLeft' || event.code === 'ArrowDown') {
      this.decreaseOneStep();
      event.preventDefault();
      return;
    }
    if (event.code === 'ArrowRight' || event.code === 'ArrowUp') {
      this.increaseOneStep();
      event.preventDefault();
      return;
    }
    if (event.code === 'Home') {
      this.setToMin();
      event.preventDefault();
      return;
    }
    if (event.code === 'End') {
      this.setToMax();
      event.preventDefault();
    }
  }

  private decreaseOneStep() {
    if (this.isFirstThumbSelected()) {
      this.fromValue = this.constrained(this.rounded(this.fromValue - this.step));
    } else {
      this.toValue = this.constrained(this.rounded(this.toValue - this.step));
    }
  }

  private increaseOneStep() {
    if (this.isFirstThumbSelected()) {
      this.fromValue = this.constrained(this.rounded(this.fromValue + this.step));
    } else {
      this.toValue = this.constrained(this.rounded(this.toValue + this.step));
    }
  }

  private setToMax() {
    const max = this.constrained(this.max);
    if (this.isFirstThumbSelected()) {
      this.fromValue = max;
    } else {
      this.toValue = max;
    }
  }

  private setToMin() {
    const min = this.constrained(this.min);
    if (this.isFirstThumbSelected()) {
      this.fromValue = min;
    } else {
      this.toValue = min;
    }
  }

  @Listen('mousedown')
  onDragStart(e) {
    if (this.disabled) return;

    if (this.isFirstThumbPressed(e)) {
      this.setFirstThumbDragged();
      return;
    }
    if (this.isSecondThumbPressed(e)) {
      this.setSecondThumbDragged();
      return;
    }

    if (this.isTrackPressed(e)) {
      if (this.closerToFirstThumb(e)) {
        this.setFirstThumbDragged();
      } else {
        this.setSecondThumbDragged();
      }
      this.onSliderMoved(e);
    }
  }

  private setSecondThumbDragged() {
    this.isSecondThumbDragged = true;
    this.firstTooltip().style.zIndex = '0';
    this.secondTooltip().style.zIndex = '1';
    this.secondThumb().classList.add('active');
  }

  private setFirstThumbDragged() {
    this.isFirstThumbDragged = true;
    this.firstTooltip().style.zIndex = '1';
    this.secondTooltip().style.zIndex = '0';
    this.firstThumb().classList.add('active');
  }

  private closerToFirstThumb(e) {
    return (
      Math.abs(this.trackPositionToValue(e.clientX) - this.fromValue) <
      Math.abs(this.trackPositionToValue(e.clientX) - this.toValue)
    );
  }

  private isTrackPressed(e) {
    return e.composedPath().includes(this.track());
  }

  private isFirstThumbPressed(e) {
    return e.composedPath().includes(this.firstThumb());
  }

  private isSecondThumbPressed(e) {
    return e.composedPath().includes(this.secondThumb());
  }

  @Listen('mouseup', { target: 'window' })
  onDragEnd() {
    this.isFirstThumbDragged = false;
    this.firstThumb().classList.remove('active');
    this.isSecondThumbDragged = false;
    this.secondThumb().classList.remove('active');
  }

  @Listen('mousemove', { target: 'window' })
  onDrag(e) {
    if (!this.isFirstThumbDragged && !this.isSecondThumbDragged) return;
    this.onSliderMoved(e);
  }

  @Watch('isFirstThumbDragged')
  @Watch('isSecondThumbDragged')
  onDraggedChanged() {
    if (this.isFirstThumbDragged || this.isSecondThumbDragged) {
      if (this.showDragTooltip) this.showTooltips();
    } else {
      this.hideTooltips();
    }
  }

  private hideTooltips() {
    this.firstTooltip().style.opacity = '0';
    this.secondTooltip().style.opacity = '0';
  }

  private showTooltips() {
    this.firstTooltip().style.opacity = '1';
    this.secondTooltip().style.opacity = '1';
  }

  @Watch('fromValue')
  @Watch('toValue')
  onFromValueChanged() {
    this.displayValues();

    const eventDetails = {
      fromValue: this.fromValue,
      toValue: this.toValue,
    };
    this.groupuiChange.emit(eventDetails);
    const event = new CustomEvent('change', {
      detail: {
        ...eventDetails,
      },
    });

    this.host.dispatchEvent(event);
  }

  private roundToNearestStep(value) {
    if (this.step === 0) return value;

    return Math.round(value / this.step) * this.step;
  }

  private displayValues() {
    this.moveFirstThumb();
    this.moveSecondThumb();
    this.moveFirstTooltip();
    this.moveSecondTooltip();
    this.adjustFill();
  }

  private constrained(value): number {
    if (this.isFirstThumbDragged || this.isFirstThumbSelected()) {
      return Math.max(this.min, Math.min(this.toValue - this.step, value));
    }
    return Math.max(this.fromValue + this.step, Math.min(this.max, value));
  }

  private isFirstThumbSelected() {
    return this.host.shadowRoot.activeElement === this.firstThumb();
  }

  private rounded(value): number {
    return Math.round((value + Number.EPSILON) * 100) / 100;
  }

  private onSliderMoved(event) {
    const value = this.constrained(this.rounded(this.roundToNearestStep(this.trackPositionToValue(event.clientX))));
    if (this.isFirstThumbDragged) {
      this.fromValue = value;
      return;
    }
    this.toValue = value;
  }

  private trackPositionToValue(pos: number) {
    return (this.max - this.min) * this.fillRatio(pos) + this.min;
  }

  private moveFirstThumb() {
    this.moveThumb(this.firstThumb(), this.fromValue);
  }

  private moveSecondThumb() {
    this.moveThumb(this.secondThumb(), this.toValue);
  }

  private moveFirstTooltip() {
    this.moveTooltip(this.firstTooltip(), this.fromValue);
  }

  private moveSecondTooltip() {
    this.moveTooltip(this.secondTooltip(), this.toValue);
  }

  private moveThumb(thumb: HTMLElement, value: number) {
    thumb.style.left = `${this.fillPercentage(value)}%`;
  }

  private moveTooltip(tooltip: HTMLElement, value: number) {
    tooltip.style.left = `${this.fillPercentage(value)}%`;
  }

  private fillPercentage(value: number): number {
    return this.percentageOnTrack(value);
  }

  private percentageOnTrack(value: number): number {
    return ((value - this.min) / (this.max - this.min)) * 100;
  }

  private adjustFill() {
    this.fill().style.left = `${this.fillPercentage(this.fromValue)}%`;
    this.fill().style.right = `${100 - this.fillPercentage(this.toValue)}%`;
  }

  private fillRatio(clampedPosition): number {
    return (
      (clampedPosition - this.track().getBoundingClientRect().left) /
      (this.track().getBoundingClientRect().right - this.track().getBoundingClientRect().left)
    );
  }

  componentDidLoad() {
    this.displayValues();
    this.addFormsHandling();
    this.addAriaLabels();
    this.groupuiDidLoad.emit();
  }

  private addFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, `${this.fromValue}:${this.toValue}`);
    });
  }

  private firstTooltip(): HTMLElement {
    return this.host.shadowRoot.querySelectorAll<HTMLElement>('.tooltip')[0];
  }

  private secondTooltip(): HTMLElement {
    return this.host.shadowRoot.querySelectorAll<HTMLElement>('.tooltip')[1];
  }

  private firstThumb(): HTMLElement {
    return this.host.shadowRoot.querySelectorAll<HTMLElement>('.thumb')[0];
  }

  private secondThumb(): HTMLElement {
    return this.host.shadowRoot.querySelectorAll<HTMLElement>('.thumb')[1];
  }

  private track(): HTMLElement {
    return this.host.shadowRoot.querySelector('.track');
  }

  private fill(): HTMLElement {
    return this.host.shadowRoot.querySelector('.fill');
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private tickMarkCount(): number {
    if (this.step === 0 || !this.showTickMarks) return 0;
    return (this.max - this.min) / this.step;
  }

  private tickMarks(): HTMLElement[] {
    const tickMarks = [<div class="tick-mark first" data-value={this.min} style={{ left: `0` }} />];
    for (let i = 1; i < this.tickMarkCount(); i++) {
      const percentage = this.percentageOnTrack(this.roundToNearestStep(this.min + this.step * i));
      const tickMark: HTMLElement = (
        <div class="tick-mark" data-value={i * this.step} style={{ left: `${percentage}%` }} />
      );
      tickMarks.push(tickMark);
    }
    tickMarks.push(<div class="tick-mark last" data-value={this.max} style={{ right: '0' }} />);

    return tickMarks;
  }

  private isTopInfoAvailable() {
    return this.isLabelSlotProvided() || this.valueTemplate;
  }

  private filledValueTemplate() {
    return this.valueTemplate
      .replace('{fromValue}', this.fromValue.toLocaleString(RangeSlider.browserLanguage()))
      .replace('{toValue}', this.toValue.toLocaleString(RangeSlider.browserLanguage()));
  }

  private static browserLanguage(): string {
    return window.navigator.language?.slice(0, 2);
  }

  private addAriaLabels() {
    if (this.a11yLabelFrom && this.a11yLabelTo) return;

    if (!this.isLabelSlotProvided()) {
      this.firstThumb().setAttribute('aria-label', 'Minimum');
      this.secondThumb().setAttribute('aria-label', 'Maximum');
      return;
    }

    this.firstThumb().setAttribute('aria-label', `${this.getSlotContent('label')} Minimum`);
    this.secondThumb().setAttribute('aria-label', `${this.getSlotContent('label')} Maximum`);
  }

  private getSlotContent(slotName: string): string {
    const slot = this.host.querySelector(`[slot="${slotName}"]`);
    return slot.innerHTML;
  }

  render() {
    return (
      <Host>
        {this.isTopInfoAvailable() && (
          <div class="top-info" aria-hidden="true">
            {this.isLabelSlotProvided() && (
              <label id="label" class="label">
                <slot name="label" />
              </label>
            )}
            {this.valueTemplate && <div class="value">{this.filledValueTemplate()}</div>}
          </div>
        )}
        <div class="track">
          <div class="bar">
            {this.showTickMarks && this.tickMarks()}
            <div class="fill"></div>
            <div
              role="slider"
              aria-valuemin={this.min}
              aria-valuemax={this.max}
              aria-valuenow={this.fromValue}
              aria-label={this.a11yLabelFrom}
              class="thumb"
              id="first-thumb"
              tabIndex={this.disabled ? -1 : 0}
            ></div>
            <div
              role="slider"
              aria-valuemin={this.min}
              aria-valuemax={this.max}
              aria-valuenow={this.toValue}
              aria-label={this.a11yLabelTo}
              class="thumb"
              id="second-thumb"
              tabIndex={this.disabled ? -1 : 0}
            ></div>
            <div class="tooltip" id="label-from" aria-hidden="true">
              <span>{this.fromValue}</span>
            </div>
            <div class="tooltip" id="label-to" aria-hidden="true">
              <span>{this.toValue}</span>
            </div>
          </div>
        </div>
        {this.isDescriptionSlotProvided() && (
          <div class="description" aria-hidden="true">
            <slot name="description" />
          </div>
        )}
      </Host>
    );
  }
}
